  function applyImageView(){if(byId('image-zoom'))byId('image-zoom').textContent=Math.round(imageUi.factor*100)+'%';document.querySelectorAll('.image-canvas img').forEach(img=>{const canvas=img.parentElement,fit=imageUi.zoom==='fit'?Math.min(1,canvas.clientWidth/img.naturalWidth,canvas.clientHeight/img.naturalHeight):1,scale=fit*imageUi.factor;img.style.transform='translate(calc(-50% + '+imageUi.panX+'px),calc(-50% + '+imageUi.panY+'px)) scale('+scale+')'});saveImageUi()}
  function initImagePan(){document.querySelectorAll('.image-canvas').forEach(canvas=>{canvas.onpointerdown=event=>{if(!canvas.querySelector('img'))return;event.preventDefault();canvas.setPointerCapture(event.pointerId);const startX=event.clientX,startY=event.clientY,panX=imageUi.panX,panY=imageUi.panY;canvas.onpointermove=e=>{imageUi.panX=panX+e.clientX-startX;imageUi.panY=panY+e.clientY-startY;applyImageView()};canvas.onpointerup=()=>{canvas.onpointermove=null;saveImageUi()}};canvas.onwheel=event=>{const img=canvas.querySelector('img');if(!img||imageUi.busy)return;event.preventDefault();const bounds=canvas.getBoundingClientRect(),fit=imageUi.zoom==='fit'?Math.min(1,canvas.clientWidth/img.naturalWidth,canvas.clientHeight/img.naturalHeight):1,next=Math.max(.1,Math.min(8,imageUi.factor*(event.deltaY<0?1.15:1/1.15))),ratio=next/imageUi.factor,x=event.clientX-bounds.left-bounds.width/2,y=event.clientY-bounds.top-bounds.height/2;imageUi.panX=x-(x-imageUi.panX)*ratio;imageUi.panY=y-(y-imageUi.panY)*ratio;imageUi.factor=next;applyImageView()}})}
  function initImageSplitters(){const body=document.querySelector('.image-body'),splitters=[...document.querySelectorAll('[data-image-resize]')];splitters.forEach(handle=>handle.onpointerdown=event=>{event.preventDefault();handle.setPointerCapture(event.pointerId);handle.classList.add('dragging');const start=event.clientX,list=byId('image-entries').getBoundingClientRect().width,original=body.querySelectorAll('.image-view')[0].getBoundingClientRect().width;handle.onpointermove=e=>{if(handle.dataset.imageResize==='list')document.documentElement.style.setProperty('--image-list-width',Math.max(220,list+e.clientX-start)+'px');else document.documentElement.style.setProperty('--image-original-width',Math.max(320,original+e.clientX-start)+'px')};handle.onpointerup=()=>{handle.classList.remove('dragging');handle.onpointermove=null;saveImageUi()}});const horizontal=document.querySelector('.image-source-splitter');if(horizontal)horizontal.onpointerdown=event=>{event.preventDefault();horizontal.setPointerCapture(event.pointerId);horizontal.classList.add('dragging');const start=event.clientY,height=document.querySelector('.image-source').getBoundingClientRect().height;horizontal.onpointermove=e=>document.documentElement.style.setProperty('--image-source-height',Math.max(160,height+start-e.clientY)+'px');horizontal.onpointerup=()=>{horizontal.classList.remove('dragging');horizontal.onpointermove=null;saveImageUi()}}}
  function renderImageSource(){const host=document.querySelector('.image-source'),lines=source.content.split(String.fromCharCode(10)),refs=activeImageItem?.lines||[];if(!host)return;imageUi.sourceIndex=Math.min(imageUi.sourceIndex,Math.max(0,refs.length-1));host.innerHTML='<div class="image-source-toolbar"><b>完整 Markdown 原文</b><button id="image-source-prev" '+(refs.length<2?'disabled':'')+'>上一处引用</button><span>第 '+(refs.length?imageUi.sourceIndex+1:0)+'/'+refs.length+' 处</span><button id="image-source-next" '+(refs.length<2?'disabled':'')+'>下一处引用</button></div><pre class="image-source-code">'+lines.map((line,index)=>'<span class="image-source-line '+(refs.includes(index+1)?'ref ':'')+(refs[imageUi.sourceIndex]===index+1?'current':'')+'" data-source-line="'+(index+1)+'">'+esc(String(index+1).padStart(4,' ')+': '+line)+'</span>').join('')+'</pre>';const locate=()=>host.querySelector('[data-source-line="'+refs[imageUi.sourceIndex]+'"]')?.scrollIntoView({block:'center'});byId('image-source-prev').onclick=()=>{imageUi.sourceIndex=(imageUi.sourceIndex-1+refs.length)%refs.length;renderImageSource();saveImageUi()};byId('image-source-next').onclick=()=>{imageUi.sourceIndex=(imageUi.sourceIndex+1)%refs.length;renderImageSource();saveImageUi()};requestAnimationFrame(locate)}
  function contextText(value){return [value?.before?.text,...(value?.target||[]).map(item=>item.text),value?.after?.text].filter(Boolean).join('\n\n')}
  function translationContextMarkup(value,currentLabel){const block=(kind,label,html)=>'<section class="translation-context-block translation-context-'+kind+'"><div class="translation-context-label">'+label+'</div><div class="translation-markdown">'+(html||'<p>无</p>')+'</div></section>';return '<div class="translation-context-flow">'+block('before','前一块',value?.before?.html)+block('current',currentLabel,(value?.target||[]).map(item=>item.html).join(''))+block('after','后一块',value?.after?.html)+'</div>'}
  function hydrateTranslationContext(host,locale,path){host.querySelectorAll('.translation-markdown p').forEach(p=>{if(!p.textContent.trim()&&p.children.length&&[...p.children].every(child=>child.tagName==='IMG'))p.classList.add('standalone-image')});host.querySelectorAll('.translation-markdown img[src]').forEach(img=>{const resource=img.getAttribute('src');if(resource&&!/^(?:[a-z][a-z0-9+.-]*:|\/\/|#)/i.test(resource))img.src='/api/feedback/resource?token='+encodeURIComponent(TOKEN)+'&book='+encodeURIComponent(translationDraft.book)+'&locale='+encodeURIComponent(locale)+'&path='+encodeURIComponent(path)+'&resource='+encodeURIComponent(resource)})}
  function refreshTranslationContexts(){const host=byId('translation-box'),draft=translationDraft,sourceSelection=host.querySelector('.translation-source .translation-selection'),sourceRow=host.querySelector('.translation-source .translation-context-row');if(sourceSelection){sourceSelection.insertAdjacentHTML('afterend',translationContextMarkup(draft.source.context,'原块'));sourceRow?.remove();hydrateTranslationContext(host.querySelector('.translation-source'),draft.source.locale,draft.source.path)}host.querySelectorAll('[data-target-panel]').forEach(panel=>{const target=draft.targets[+panel.dataset.targetPanel],row=panel.querySelector('.translation-context-row');if(!target||!row)return;row.outerHTML=translationContextMarkup(target.context,'当前块');hydrateTranslationContext(panel,target.locale,target.path)})}
  function translationPromptContext(target){const value=JSON.stringify({source:translationDraft.source.context,target:target.context});target.contextClipped=value.length>60000;return target.contextClipped?value.slice(0,30000)+value.slice(-30000):value}
  function methodOptions(selected,capabilities){const labels={ai:'AI 接口',codex:'Codex CLI',google:'Google 翻译网页',bing:'必应翻译网页'};return Object.entries(capabilities.methods).map(([id,item])=>'<option value="'+id+'" '+(id===selected?'selected':'')+' '+(item.available?'':'disabled')+'>'+labels[id]+(item.available?'':'（'+item.reason+'）')+'</option>').join('')}
  async function translateSelection(){if(translationDraft)return notify('warning','当前已有翻译草稿，请先完成或放弃。');if(dirty)return notify('warning','请先保存源语言文件，再进行跨语言翻译。');const selection=editor.getSelection();if(!selection.text)return notify('warning','请先在文件编辑中选择要翻译的文字。');try{const draft=await api('/api/feedback/translation-prepare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({book:byId('book').value,source_locale:activeLocale,path:source.path,from:selection.from,to:selection.to})});draft.book=byId('book').value;draft.source.content=source.content;draft.source.position=selection;draft.defaultMethod=draft.capabilities.default;draft.targets.forEach(target=>Object.assign(target,{method:draft.defaultMethod,status:'pending',candidate:'',initialCandidate:'',differences:[],confirmed:false,manual:false,ignored:false,opened:false,expanded:false}));translationDraft=draft;renderWorkbench(source);showTranslationDraft()}catch(error){notify('error',error.message)}}
