  function translationLocked(target){return target.ignored||target.manual||target.externalChanged||translationDraft?.sourceChanged}
  async function showTranslationDraft(){if(!translationDraft)return;showTab('translation');try{const current=await api('/api/feedback/translation-prepare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({book:translationDraft.book,source_locale:translationDraft.source.locale,path:translationDraft.source.path,from:translationDraft.source.selection.from,to:translationDraft.source.selection.to})});translationDraft.sourceChanged=JSON.stringify(current.source.state)!==JSON.stringify(translationDraft.source.state);translationDraft.targets.forEach(target=>{const latest=current.targets.find(item=>item.locale===target.locale);target.externalChanged=!!latest&&JSON.stringify(latest.state)!==JSON.stringify(target.state)})}catch(error){notify('error','翻译草稿状态检查失败：'+error.message)}renderTranslationDraft()}
  function renderTranslationDraft(){const draft=translationDraft,host=byId('translation-box'),done=draft.targets.filter(t=>t.confirmed||t.manual||t.ignored).length;host.innerHTML='<div class="translation-head"><b>多语言翻译对照</b><span>'+done+'/'+draft.targets.length+' 个目标语言已处理</span><label>默认方式 <select id="translation-default">'+methodOptions(draft.defaultMethod,draft.capabilities)+'</select></label><button id="translation-source-file">返回源文件</button><button id="translation-discard">放弃草稿</button></div><div class="translation-grid"><section class="translation-source"><h3>'+esc(draft.source.locale)+' · 源语言</h3><div class="translation-path">'+esc(draft.source.path)+'</div><div class="translation-selection">'+esc(draft.source.selection.text)+'</div><details><summary>源语言前后文</summary><pre>'+esc(contextText(draft.source.context))+'</pre></details></section><section><div class="translation-languages">'+draft.targets.map((target,index)=>'<button data-translation-target="'+index+'" class="'+(index===(draft.activeTarget||0)?'active':'')+'">'+esc(target.locale)+' · '+translationStatus(target)+'</button>').join('')+'</div><div id="translation-target-panel"></div></section></div><div class="translation-save"><span>'+((done===draft.targets.length)?'所有语言已处理，可以统一保存。':'尚有 '+(draft.targets.length-done)+' 个语言未完成。')+'</span><button id="translation-commit" '+(done===draft.targets.length?'':'disabled')+'>统一保存所有语言</button></div>';byId('translation-default').onchange=e=>{draft.defaultMethod=e.target.value;api('/api/feedback/translation-method',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:draft.defaultMethod})}).catch(error=>notify('error',error.message));draft.targets.filter(t=>t.status==='pending'&&!t.candidate).forEach(t=>t.method=draft.defaultMethod);renderTranslationDraft()};host.querySelectorAll('[data-translation-target]').forEach(button=>button.onclick=()=>{draft.activeTarget=+button.dataset.translationTarget;renderTranslationDraft()});byId('translation-source-file').onclick=()=>loadLocale(draft.source.path,draft.source.locale,true);byId('translation-discard').onclick=()=>confirmInline('确认放弃当前多语言翻译草稿？',()=>{translationDraft=null;renderWorkbench(source)});byId('translation-commit').onclick=commitTranslation;renderTranslationTarget(draft.targets[draft.activeTarget||0])}
  function renderTranslationTarget(target){const panel=byId('translation-target-panel');if(!target)return panel.innerHTML='<div class="empty">当前书册没有目标语言。</div>';const disabled=target.ignored||target.manual;panel.innerHTML='<article class="translation-target"><div class="translation-target-head"><b>'+esc(target.locale)+' · '+esc(target.language)+'</b><span>'+translationStatus(target)+'</span></div><div class="translation-path">'+esc(target.path)+'</div><div class="translation-flags"><label><input id="translation-manual" type="checkbox" '+(target.manual?'checked':'')+' '+(!target.exists||!target.opened?'disabled':'')+'>已人工处理</label><label><input id="translation-ignore" type="checkbox" '+(target.ignored?'checked':'')+'>忽略此语言</label></div><div class="'+(target.reliable?'translation-ok':'translation-warning')+'">'+esc(target.exists?(target.reliable?'目标块结构匹配，可自动应用完整块候选。':target.reason):target.reason)+'</div>'+(target.exists?'<div class="translation-context"><h4>目标语言上下文</h4><pre>'+esc(contextText(target.context))+'</pre><details '+(target.expanded?'open':'')+'><summary>展开完整目标文件源码</summary><pre>'+esc(target.content)+'</pre></details></div>':'')+'<div class="translation-candidate"><label>翻译方式 <select id="translation-method" '+(disabled?'disabled':'')+'>'+methodOptions(target.method,translationDraft.capabilities)+'</select></label><button id="translation-run" '+(disabled||!target.exists?'disabled':'')+'>'+(target.candidate?'重新翻译':'生成翻译候选')+'</button><button id="translation-web" class="hidden">打开翻译网页</button><textarea id="translation-candidate" '+(disabled||target.confirmed?'readonly':'')+' placeholder="翻译候选将在这里显示，也可以粘贴或手动修改">'+esc(target.candidate)+'</textarea><div id="translation-validation" class="'+(target.differences.length?'translation-warning':'translation-ok')+'">'+esc(target.differences.join('；'))+'</div><button id="translation-confirm" '+(disabled||!target.candidate||target.differences.length||!target.reliable||!translationDraft.source.selection.complete_blocks?'disabled':'')+'>'+(target.confirmed?'重新编辑候选':'确认此候选')+'</button><button id="translation-restore" '+(!target.initialCandidate||disabled?'disabled':'')+'>恢复初始翻译结果</button><button id="translation-open" '+(!target.exists?'disabled':'')+'>在编辑器中打开并人工处理</button></div></article>';byId('translation-method').onchange=e=>{target.method=e.target.value;target.confirmed=false};byId('translation-run').onclick=()=>runTranslation(target);byId('translation-candidate').oninput=e=>{target.candidate=e.target.value;target.confirmed=false;validateTranslation(target)};byId('translation-confirm').onclick=()=>{target.confirmed=!target.confirmed;renderTranslationDraft()};byId('translation-restore').onclick=()=>{target.candidate=target.initialCandidate;target.confirmed=false;validateTranslation(target)};byId('translation-open').onclick=()=>{target.opened=true;loadLocale(target.path,target.locale,true)};byId('translation-manual').onchange=e=>{target.manual=e.target.checked;target.ignored=false;target.confirmed=false;if(target.manual&&source?.locale===target.locale){target.state=source.state;target.manualChanged=source.content!==target.content}renderTranslationDraft()};byId('translation-ignore').onchange=e=>{target.ignored=e.target.checked;target.manual=false;target.confirmed=false;renderTranslationDraft()};if(['google','bing'].includes(target.method)){byId('translation-web').classList.remove('hidden');byId('translation-web').onclick=()=>openTranslationWeb(target)}}
  async function runTranslation(target){if(['google','bing'].includes(target.method)){openTranslationWeb(target);return}target.status='running';renderTranslationDraft();try{const providers=await api('/api/feedback/providers'),context=JSON.stringify({source:translationDraft.source.context,target:target.context});const value=await api('/api/feedback/translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:target.method,provider:providers.providers[0]?.id,source_locale:translationDraft.source.locale,targets:[target.locale],text:translationDraft.source.selection.text,title:translationDraft.source.path,context})}),item=value.results[0];target.status=item.status==='ready'?'ready':'failed';target.candidate=item.text||'';target.initialCandidate=target.candidate;target.differences=item.differences||[];renderTranslationDraft()}catch(error){target.status='failed';target.error=error.message;notify('error',target.locale+' 翻译失败：'+error.message);renderTranslationDraft()}}
  function openTranslationWeb(target){const text=translationDraft.source.scope.text,url=target.method==='google'?'https://translate.google.com/?sl='+translationDraft.source.locale+'&tl='+target.locale+'&text='+encodeURIComponent(text)+'&op=translate':'https://www.bing.com/translator?from='+translationDraft.source.locale+'&to='+target.locale+'&text='+encodeURIComponent(text);window.open(url,'_blank','noopener')}
